import { useFrame } from '@react-three/fiber'
import { lazyModule, planeWater, useNodeRenderer, useWater, useWorld, type Vec3 } from '@runek/core'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import type { WaterShape } from './nodes/water'
import { lakeSurface } from './surfaces/lake'
import { swellAt, UNDERSIDE } from './surfaces/water'

// The WebGPU (TSL) twin of the shader below, loaded only under a node renderer.
const waterNodes = lazyModule(() => import('./nodes/water'))
const WATER: WaterShape = {
  freq: [0.6, 0.4, 0.2, 0.8, 1.5],
  chop: 1.6,
  eps: 0.35,
  world: false,
  sky: 0.55,
  glint: [70, 0.7],
  crest: 0.4,
  alpha: [0.78, 0.18],
  fog: false,
}
/** How far a camera under the lake sees through it, in units: murkier than the sea. */
const CLARITY = 16

export interface LakeProps {
  position?: Vec3
  rotation?: Vec3
  /** Accepted for the component contract; this component has no seeded variation yet. */
  seed?: number
  /** Water surface `[width, depth]`, in units. */
  size?: [number, number]
  /** Defaults to the world palette's `waterDeep` slot. */
  colorDeep?: string
  /** Defaults to the world palette's `waterShallow` slot. */
  colorShallow?: string
  /** Direction the sun glint comes from; pair with your Sky's `sunPosition`. */
  sunPosition?: Vec3
  waveHeight?: number
  waveSpeed?: number
  segments?: number
}

const VERTEX = /* glsl */ `
  uniform float uTime;
  uniform float uWaveHeight;
  uniform float uWaveSpeed;
  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vWave;

  float waveH(vec2 q, float t) {
    float w1 = sin(q.x * 0.6 + t) * cos(q.y * 0.4 + t * 0.8);
    float w2 = sin(q.x * 0.2 - t * 0.7) * sin(q.y * 0.8 + t);
    float w3 = sin((q.x + q.y) * 1.5 + t * 1.6) * 0.25;
    return (w1 + w2 + w3) * 0.5;
  }

  void main() {
    float t = uTime * uWaveSpeed;
    vec3 p = position;
    float h = waveH(p.xy, t);
    vWave = h;
    p.z += h * uWaveHeight;

    // finite-difference normal so the light reacts to the waves
    float eps = 0.35;
    float hx = waveH(position.xy + vec2(eps, 0.0), t);
    float hy = waveH(position.xy + vec2(0.0, eps), t);
    vec3 n = normalize(vec3(-(hx - h) * uWaveHeight / eps, -(hy - h) * uWaveHeight / eps, 1.0));
    vNormal = normalize(mat3(modelMatrix) * n);

    vWorldPos = (modelMatrix * vec4(p, 1.0)).xyz;
    gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
  }
`

const FRAGMENT = /* glsl */ `
  uniform vec3 uColorDeep;
  uniform vec3 uColorShallow;
  uniform vec3 uSunDir;
  uniform float uFogNear;
  uniform float uFogFar;
  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vWave;
  ${UNDERSIDE}
  void main() {
    vec3 n = normalize(vNormal);
    vec3 viewDir = normalize(cameraPosition - vWorldPos);

    float m = smoothstep(-1.0, 1.0, vWave);
    vec3 col = mix(uColorDeep, uColorShallow, m);

    // sky tint at grazing angles
    float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 3.0);
    col = mix(col, vec3(0.62, 0.78, 0.9), fresnel * 0.55);

    // sun glint
    vec3 r = reflect(-uSunDir, n);
    float glint = pow(max(dot(r, viewDir), 0.0), 70.0);
    col += vec3(1.0, 0.95, 0.85) * glint * 0.7;

    // crest brighten, as before
    col += pow(max(m - 0.6, 0.0), 2.0) * 0.4;

    float alpha = 0.78 + fresnel * 0.18;

    gl_FragColor = gl_FrontFacing
      ? vec4(col, alpha)
      : underside(n, viewDir, m, distance(cameraPosition, vWorldPos));
  }
`

/** Procedural animated water (no textures, no collider). The local origin is the water
 *  surface: place it at or below the surrounding ground so it fills a depression rather than
 *  floating (CONTRACT §10). It is water a `Player` or a `Person` swims in wherever the ground
 *  under it leaves the water over half their height, and it is drawn from below too. */
export function Lake({
  position,
  rotation = [0, 0, 0],
  size = [20, 20],
  colorDeep,
  colorShallow,
  sunPosition = [80, 30, 40],
  waveHeight = 0.12,
  waveSpeed = 1,
  segments = 64,
}: LakeProps) {
  const { unit, palette, ground } = useWorld()
  const deep = colorDeep ?? palette.waterDeep
  const shallow = colorShallow ?? palette.waterShallow
  // Surface sits at the world ground baseline by default; explicit position wins.
  const pos = position ?? [0, ground, 0]
  const w = size[0] * unit
  const d = size[1] * unit
  // By its numbers: the default is a new array every render, and new uniforms restart the waves.
  const [sunX, sunY, sunZ] = sunPosition
  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uWaveHeight: { value: waveHeight * unit },
      uWaveSpeed: { value: waveSpeed },
      uColorDeep: { value: new THREE.Color(deep) },
      uColorShallow: { value: new THREE.Color(shallow) },
      uSunDir: { value: new THREE.Vector3(sunX, sunY, sunZ).normalize() },
      // The fog's range, for the underside: from below, the surface is gone where the fog closes.
      uFogNear: { value: 1e6 },
      uFogFar: { value: 1e7 },
    }),
    [waveHeight, waveSpeed, deep, shallow, sunX, sunY, sunZ, unit],
  )

  // Built here, not as a `<shaderMaterial>`: react-three-fiber copies the uniforms it is handed
  // into the material, so the clock and the fog range written each frame would never reach it.
  const nodes = useNodeRenderer() ? waterNodes() : null
  const material = useMemo(
    () =>
      nodes?.waterMaterial(uniforms, WATER) ??
      new THREE.ShaderMaterial({
        uniforms,
        vertexShader: VERTEX,
        fragmentShader: FRAGMENT,
        transparent: true,
        // Both sides in one draw: from below it is the surface a diver looks up at.
        side: THREE.DoubleSide,
        forceSinglePass: true,
      }),
    [nodes, uniforms],
  )
  useEffect(() => () => material.dispose(), [material])

  const meshRef = useRef<THREE.Mesh>(null)
  const water = useMemo(
    () =>
      planeWater(() => meshRef.current, [w, d], {
        wave: (lx, ly) =>
          swellAt(WATER, lx, ly, uniforms.uTime.value * uniforms.uWaveSpeed.value) *
          uniforms.uWaveHeight.value,
        color: deep,
        clarity: CLARITY * unit,
      }),
    [w, d, uniforms, deep, unit],
  )
  useWater(water)

  useFrame((state, delta) => {
    uniforms.uTime.value += delta
    const fog = state.scene.fog
    if (fog && 'near' in fog) {
      const linear = fog as THREE.Fog
      uniforms.uFogNear.value = linear.near
      uniforms.uFogFar.value = linear.far
    }
  })

  return (
    <mesh
      ref={meshRef}
      position={pos}
      rotation={[-Math.PI / 2 + rotation[0], rotation[1], rotation[2]]}
    >
      <planeGeometry args={[w, d, segments, segments]} />
      <primitive object={material} attach="material" />
    </mesh>
  )
}

Lake.surface = lakeSurface

import type { SurfaceDef } from '@runek/core'

const sizeOf = (props: Record<string, unknown>) =>
  (props.size as [number, number] | undefined) ?? [20, 20]

/** Lake's water plane. An unplaced Lake sits at `world.ground`. Its rim is what the world
 *  check compares against the ground: open water must not stand above its shore. */
export const lakeSurface: SurfaceDef = {
  kind: 'water',
  build(props, { unit, ground }) {
    const [w, d] = sizeOf(props)
    const level = props.position === undefined ? ground : 0
    return (x, z) => (Math.abs(x) <= (w * unit) / 2 && Math.abs(z) <= (d * unit) / 2 ? level : null)
  },
  rim(props, { unit }) {
    const [w, d] = sizeOf(props)
    const hw = (w * unit) / 2
    const hd = (d * unit) / 2
    return [
      [-hw, -hd],
      [0, -hd],
      [hw, -hd],
      [hw, 0],
      [hw, hd],
      [0, hd],
      [-hw, hd],
      [-hw, 0],
    ]
  },
}

// The water shaders' swell in plain TS: the same wave the GLSL and node materials draw, so a
// swimmer rides the surface that is on screen.

/** Wave frequencies (first wave x and y, second wave x and y, the diagonal chop) and how fast the
 *  chop runs against the clock: the numbers a water shader is written with. */
export interface Swell {
  freq: [number, number, number, number, number]
  chop: number
}

/** Height of the swell at (x, y) of the water's wave coordinates at wave time `t`, for a wave
 *  height of 1. Mirrors `waveH` in `Lake` and `Ocean`. */
export function swellAt({ freq, chop }: Swell, x: number, y: number, t: number) {
  const w1 = Math.sin(x * freq[0] + t) * Math.cos(y * freq[1] + t * 0.8)
  const w2 = Math.sin(x * freq[2] - t * 0.7) * Math.sin(y * freq[3] + t)
  const w3 = Math.sin((x + y) * freq[4] + t * chop) * 0.25
  return (w1 + w2 + w3) * 0.5
}

/**
 * GLSL for a water surface seen from below, for a fragment shader that declares `uColorDeep`,
 * `uColorShallow`, `uSunDir`, `uFogNear` and `uFogFar` first. From below the surface is a layer
 * over what lies past it: the sky's light through a window straight overhead (light from above
 * enters the water no flatter than 49 degrees from straight down), a shade of the deep water
 * past that, and nothing at all by the distance the water's fog closes at, so it melts into
 * whatever stands for the water beyond (`Underwater`'s backdrop). `n` is the surface's normal up
 * out of the water, `viewDir` runs from the surface to the camera, `m` is the wave's height from
 * 0 to 1, `far` how far off the surface is. Returns the color and how much of it shows.
 */
export const UNDERSIDE = /* glsl */ `
  vec4 underside(vec3 n, vec3 viewDir, float m, float far) {
    float window = smoothstep(0.6, 0.8, max(dot(-viewDir, n), 0.0));
    vec3 col = mix(uColorDeep * 0.5, mix(uColorShallow, vec3(0.62, 0.78, 0.9), 0.7), window);
    col *= 0.9 + 0.2 * m;
    // The sun, where its light comes down through the surface.
    float sun = pow(max(dot(viewDir, refract(-uSunDir, n, 0.75)), 0.0), 60.0);
    col += vec3(1.0, 0.95, 0.85) * sun * 0.7;
    float alpha = mix(0.4, 0.8, window) + sun * 0.2;
    return vec4(col, min(alpha, 1.0) * (1.0 - smoothstep(uFogNear, uFogFar, far)));
  }
`

import { type Color, DoubleSide, type Vector3 } from 'three'
import {
  cameraPosition,
  cos,
  distance,
  dot,
  float,
  frontFacing,
  max,
  min,
  mix,
  modelWorldMatrix,
  normalize,
  positionLocal,
  pow,
  reflect,
  refract,
  select,
  sin,
  smoothstep,
  sRGBTransferEOTF,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { follow } from './uniforms'

/** What one body of water's waves and shading look like (the numbers its GLSL shader uses). */
export interface WaterShape {
  /** Wave frequencies: first wave x and y, second wave x and y, the diagonal chop. */
  freq: [number, number, number, number, number]
  /** How fast the diagonal chop runs against the clock. */
  chop: number
  /** Finite-difference step for the normal. */
  eps: number
  /** Waves in world XZ (they stay put while the mesh follows the camera) or in the mesh's own. */
  world: boolean
  /** How much sky tints the water at grazing angles. */
  sky: number
  /** Sun glint exponent and strength. */
  glint: [number, number]
  /** Crest brightening. */
  crest: number
  /** Base opacity, and what grazing angles add. */
  alpha: [number, number]
  /** Blend into distance fog (needs the fog uniforms). */
  fog: boolean
}

export interface WaterUniforms {
  uTime: { value: number }
  uWaveHeight: { value: number }
  uWaveSpeed: { value: number }
  uColorDeep: { value: Color }
  uColorShallow: { value: Color }
  uSunDir: { value: Vector3 }
  uFogColor?: { value: Color }
  uFogNear?: { value: number }
  uFogFar?: { value: number }
}

/** The node (TSL) twin of `Lake`'s and `Ocean`'s GLSL water, for `WebGPURenderer`. */
export function waterMaterial(record: WaterUniforms, shape: WaterShape) {
  const time = follow<Node<'float'>>(record.uTime)
  const waveHeight = follow<Node<'float'>>(record.uWaveHeight)
  const waveSpeed = follow<Node<'float'>>(record.uWaveSpeed)
  const deep = follow<Node<'vec3'>>(record.uColorDeep)
  const shallow = follow<Node<'vec3'>>(record.uColorShallow)
  const sunDir = follow<Node<'vec3'>>(record.uSunDir)
  const [fx1, fy1, fx2, fy2, fd] = shape.freq

  const waveH = (q: Node<'vec2'>, t: Node<'float'>): Node<'float'> => {
    const w1 = sin(q.x.mul(fx1).add(t)).mul(cos(q.y.mul(fy1).add(t.mul(0.8))))
    const w2 = sin(q.x.mul(fx2).sub(t.mul(0.7))).mul(sin(q.y.mul(fy2).add(t)))
    const w3 = sin(q.x.add(q.y).mul(fd).add(t.mul(shape.chop))).mul(0.25)
    return w1.add(w2).add(w3).mul(0.5) as Node<'float'>
  }

  const t = time.mul(waveSpeed)
  const q = (
    shape.world
      ? modelWorldMatrix.mul(vec4(positionLocal.x, positionLocal.y, 0, 1)).xz
      : positionLocal.xy
  ) as Node<'vec2'>
  const h = waveH(q, t)
  const hx = waveH(q.add(vec2(shape.eps, 0)), t)
  const hy = waveH(q.add(vec2(0, shape.eps)), t)
  const slope = waveHeight.div(shape.eps)
  const n = normalize(vec3(hx.sub(h).mul(slope).negate(), hy.sub(h).mul(slope).negate(), 1))
  const displaced = positionLocal.add(vec3(0, 0, h.mul(waveHeight)))

  const worldNormal = varying(normalize(modelWorldMatrix.mul(vec4(n, 0)).xyz))
  const worldPos = varying(modelWorldMatrix.mul(vec4(displaced, 1)).xyz)
  const wave = varying(h)

  const normal = normalize(worldNormal)
  const viewDir = normalize(cameraPosition.sub(worldPos))
  const m = smoothstep(-1, 1, wave)
  const fresnel = pow(float(1).sub(max(dot(normal, viewDir), 0)), 3)
  const glint = pow(max(dot(reflect(sunDir.negate(), normal), viewDir), 0), shape.glint[0])
  let color = mix(deep, shallow, m) as Node<'vec3'>
  color = mix(color, vec3(0.62, 0.78, 0.9), fresnel.mul(shape.sky)) as Node<'vec3'>
  color = color.add(vec3(1, 0.95, 0.85).mul(glint).mul(shape.glint[1])) as Node<'vec3'>
  color = color.add(pow(max(m.sub(0.6), 0), 2).mul(shape.crest)) as Node<'vec3'>
  let alpha = float(shape.alpha[0]).add(fresnel.mul(shape.alpha[1])) as Node<'float'>
  const far = distance(cameraPosition, worldPos)
  const fog =
    record.uFogNear && record.uFogFar
      ? smoothstep(
          follow<Node<'float'>>(record.uFogNear),
          follow<Node<'float'>>(record.uFogFar),
          far,
        )
      : null
  if (shape.fog && fog && record.uFogColor) {
    color = mix(color, follow<Node<'vec3'>>(record.uFogColor), fog) as Node<'vec3'>
    alpha = mix(alpha, float(1), fog) as Node<'float'>
  }

  // From below (`UNDERSIDE` in `surfaces/water.ts`): the sky's light through a window straight
  // overhead, a shade of the deep water past it, the sun where its light comes down through
  // the surface, and nothing by the distance the fog closes at.
  const window = smoothstep(0.6, 0.8, max(dot(viewDir.negate(), normal), 0))
  const sun = pow(max(dot(viewDir, refract(sunDir.negate(), normal, 0.75)), 0), 60)
  const under = mix(deep.mul(0.5), mix(shallow, vec3(0.62, 0.78, 0.9), 0.7), window)
    .mul(m.mul(0.2).add(0.9))
    .add(vec3(1, 0.95, 0.85).mul(sun).mul(0.7))
  const shown = min(mix(float(0.4), float(0.8), window).add(sun.mul(0.2)), 1)
  color = select(frontFacing, color, under) as Node<'vec3'>
  alpha = select(frontFacing, alpha, fog ? shown.mul(float(1).sub(fog)) : shown) as Node<'float'>

  // Both sides in one draw.
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    forceSinglePass: true,
  })
  material.positionNode = displaced
  // The GLSL shader writes its color as is (no tone mapping, no output conversion); undoing the
  // node pipeline's sRGB output conversion here shows the same color.
  material.colorNode = vec4(sRGBTransferEOTF(color) as Node<'vec3'>, alpha)
  material.toneMapped = false
  material.fog = false
  return material
}

import { float, uniform } from 'three/tsl'
import { Node, type NodeFrame, NodeUpdateType } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}

class BeforeDraw extends Node {
  constructor(private readonly run: (frame: NodeFrame) => void) {
    super('float')
    this.updateBeforeType = NodeUpdateType.OBJECT
  }

  updateBefore(frame: NodeFrame) {
    this.run(frame)
    return true
  }

  setup() {
    return float(0)
  }
}

/**
 * A node worth 0 that runs `run` before each object using it draws: add it to anything in the
 * material to have it run. For what a uniform can't do per object, like pointing a texture node at
 * another texture (a texture node resets its own update hook when it builds).
 */
export function beforeDraw(run: (frame: NodeFrame) => void): Node<'float'> {
  return new BeforeDraw(run) as unknown as Node<'float'>
}
